interface RetryOptions {
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
}

const RETRYABLE = new Set([429, 500, 502, 503, 504]);

class ApiError extends Error {
  constructor(public status: number, public retryAfterMs?: number) {
    super(`HTTP ${status}`);
  }
}

export async function callWithRetry<T>(
  fn: () => Promise<T>,
  opts: RetryOptions = {},
): Promise<T> {
  const { maxRetries = 3, baseDelayMs = 500, maxDelayMs = 8000 } = opts;
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (err) {
      const e = err as ApiError;
      const retryable = e instanceof ApiError && RETRYABLE.has(e.status);
      if (!retryable || attempt >= maxRetries) throw err;
      // 优先尊重服务端 retry-after；否则指数退避 + jitter 防惊群
      const delay = Math.min(
        e.retryAfterMs ?? baseDelayMs * 2 ** attempt,
        maxDelayMs,
      );
      await new Promise((r) => setTimeout(r, delay + Math.random() * 250));
    }
  }
}

export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) throw new Error('dimension mismatch');
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}
// 单次遍历同时算点积与范数；零向量防御除零。

为什么用 cosine：它度量方向而非幅度——embedding 的模长常受文本长度/词频影响，cosine 消除了幅度的干扰，只比较语义方向的接近程度；取值 [-1,1] 有明确语义且尺度稳定。当所有向量都已 L2 归一化时，cosine 相似度等价于点积，此时可直接用内积换取计算速度（很多向量库的 IP 度量就是这个原理）。

interface ChunkOptions {
  chunkSize: number;   // 目标字符上限
  overlap: number;     // 相邻块重叠字符数
}

export function chunkText(text: string, opts: ChunkOptions): string[] {
  const { chunkSize, overlap } = opts;
  if (overlap >= chunkSize) throw new Error('overlap must be < chunkSize');
  const chunks: string[] = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + chunkSize, text.length);
    if (end < text.length) {
      // 在窗口内找最后一个断句边界，避免切断单词/句子
      const window = text.slice(start, end);
      const boundary = Math.max(
        window.lastIndexOf(' '),
        window.lastIndexOf('\\n'),
        window.lastIndexOf('.'),
      );
      if (boundary > chunkSize * 0.5) end = start + boundary + 1;
    }
    chunks.push(text.slice(start, end).trim());
    if (end >= text.length) break;
    start = Math.max(end - overlap, start + 1); // 防 zero-progress 死循环
  }
  return chunks.filter(Boolean);
}

关键点：优先在自然边界切分（句子>空格）；边界太靠前时接受硬切避免无限膨胀；start 回退量受 overlap 约束但必须保证前进，否则死循环；生产版还应支持按段落预切分、token 计数代替字符数。

type ToolFn = (args: Record<string, unknown>) => Promise<unknown>;

interface ToolCall { name: string; arguments: string; }

class ToolHandler {
  private registry = new Map<string, ToolFn>();

  register(name: string, fn: ToolFn, schema: object): void {
    this.registry.set(name, fn);
  }

  async execute(call: ToolCall): Promise<string> {
    const tool = this.registry.get(call.name);
    if (!tool) return this.errorResult(call.name, `unknown tool: ${call.name}`);
    try {
      const args = JSON.parse(call.arguments || '{}');   // 模型输出必须当不可信输入
      const result = await tool(args);
      return JSON.stringify({ ok: true, data: result });
    } catch (err) {
      // 解析失败/执行失败都结构化返回给模型，让它有机会修正而不是崩溃
      return this.errorResult(call.name, err instanceof Error ? err.message : 'unknown');
    }
  }

  private errorResult(name: string, message: string): string {
    return JSON.stringify({ ok: false, tool: name, error: message });
  }

  async runAll(calls: ToolCall[]): Promise<Array<{ role: 'tool'; content: string }>> {
    // 多个独立调用可并发；结果以 tool role 消息回填 conversation
    const results = await Promise.all(calls.map((c) => this.execute(c)));
    return results.map((content) => ({ role: 'tool' as const, content }));
  }
}

设计要点：模型输出的 arguments 是不可信 JSON，必须 parse+校验而非直接信任；错误要结构化回传给模型形成修正闭环；未知工具名优雅降级；独立工具并发执行；超时控制生产上还应加 per-tool timeout 与幂等保护。

interface Message { role: 'user' | 'assistant'; content: string; tokens: number; }

interface Turn { user: Message; assistant?: Message; }  // 按轮组织便于摘要

class ContextManager {
  private turns: Turn[] = [];
  private summary: string | null = null;

  constructor(
    private systemPrompt: string,
    private budgetTokens: number,
    private recentTurns: number,
    private summarize: (text: string) => Promise<string>,  // 注入 LLM
  ) {}

  async buildContext(): Promise<Array<{ role: string; content: string }>> {
    const system = [{ role: 'system', content: this.systemPrompt }];
    const sysTokens = this.approxTokens(this.systemPrompt);
    const recent = this.turns.slice(-this.recentTurns);
    let older = this.turns.slice(0, -this.recentTurns);

    let total = sysTokens + this.turnTokens(recent) + (this.summary ? this.approxTokens(this.summary) : 0);

    // 预算仍不够时：从最旧开始把更多轮次并入摘要区
    while (total > this.budgetTokens && this.turns.length > 0 && older.length < this.turns.length - 1) {
      older.push(this.turns[this.turns.length - older.length - 2]);
      total = sysTokens + this.turnTokens(recent) + this.turnTokens(older) + (this.summary ? this.approxTokens(this.summary) : 0);
    }

    if (older.length > 0) {
      const raw = older.map((t) => `User: ${t.user.content}\\nAssistant: ${t.assistant?.content ?? ''}`).join('\\n\\n');
      this.summary = [this.summary, await this.summarize(raw)].filter(Boolean).join('\\n');  // 增量合并旧摘要
    }

    const msgs: Array<{ role: string; content: string }> = [...system];
    if (this.summary) msgs.push({ role: 'system', content: `此前对话摘要：${this.summary}` });
    for (const t of recent) {
      msgs.push({ role: 'user', content: t.user.content });
      if (t.assistant) msgs.push({ role: 'assistant', content: t.assistant.content });
    }
    return msgs;
  }

  private turnTokens(turns: Turn[]): number {
    return turns.reduce((s, t) => s + t.user.tokens + (t.assistant?.tokens ?? 0), 0);
  }
  private approxTokens(s: string): number { return Math.ceil(s.length / 4); }
}

设计要点：system 永远保留且不参与压缩；摘要增量合并（旧摘要+新入档内容一起总结）避免信息反复丢失；summarize 作为注入函数便于 mock 测试；生产版应记录“被压缩”标记保证可观测，并对摘要丢失的关键事实（如用户偏好）走显式 memory 而非指望摘要保留。
